//! Code highlighting with every grammar the app has, coloured as the app's Shiki
//! colours it: the grammars and the scope table are generated by
//! scripts/generate-syntax.mjs from the same sources.

use std::cell::{Ref, RefCell};
use std::collections::{HashMap, VecDeque};
use std::ops::Range;
use std::rc::Rc;
use std::sync::{Arc, Mutex, MutexGuard, OnceLock};

use gpui_kit::base::input::{
    EditorState, FoldRange, HighlightStyleResolver, InputEdit, InputHighlighter,
    InputHighlighterFactory, Rope, RopeExt,
};
use gpui_kit::{
    px, App, Context, FontStyle, FontWeight, Global, HighlightStyle, SharedString, Task,
    UnderlineStyle, Window,
};
use gpui_transcript::CodeRuns;
use textmate_highlight::{Document, Library, Span, Style, Styles};
use tokio::sync::Notify;

use sikemux_wire::theme::ThemeHighlight;

use crate::theme::{self, Tokens};

static INDEX: &[u8] = include_bytes!("../assets/syntax.json");
static GRAMMARS: &[u8] = include_bytes!("../assets/grammars.bin");

/// Longer lines are left in the text colour, as in today's editor.
const MAX_LINE_LENGTH: usize = 3_000;
/// Documents up to this size are tokenized whole; larger ones only as far down as
/// drawing has reached, and this many lines past it.
const WHOLE_MAX_BYTES: usize = 64 * 1024;
const AHEAD: usize = 200;
/// An edit that leaves at most this many lines to retokenize is done on the
/// keystroke; more go to the background.
const SYNC_MAX_LINES: usize = 400;
/// Lines tokenized between letting go of the document, so drawing never waits long.
const BACKGROUND_CHUNK: usize = 100;
/// How much text `colour_lines` keeps coloured, as today's diff colours keep.
const COLOURED_MAX_BYTES: usize = 4 * 1024 * 1024;
/// How many chat code blocks stay coloured, and how much memory their colours take in all.
const BLOCKS_MAX: usize = 64;
const BLOCKS_MAX_BYTES: usize = 4 * 1024 * 1024;
/// Longer code blocks stay in the text colour, so one block never takes the whole budget.
const BLOCK_MAX_BYTES: usize = 128 * 1024;

struct Shared {
    library: Library,
    styles: Styles,
    /// The roles whose text holds no code: braces inside them are not folded.
    quiet: Vec<u16>,
}

fn shared() -> &'static Shared {
    static SHARED: OnceLock<Shared> = OnceLock::new();
    SHARED.get_or_init(|| {
        let library = Library::new(INDEX, GRAMMARS).expect("the generated syntax bundle reads");
        let styles = Styles::new(library.theme_rules());
        let quiet = ["string", "comment"]
            .iter()
            .filter_map(|name| styles.roles().iter().position(|role| role == name))
            .map(|index| index as u16)
            .collect();
        Shared {
            library,
            styles,
            quiet,
        }
    })
}

/// The current theme's code colours, shared by every highlighter so a theme change
/// restyles open editors.
#[derive(Clone)]
struct Palette(Rc<RefCell<PaletteState>>);

struct PaletteState {
    /// Counts the themes taken since the window opened.
    version: u64,
    text: String,
    highlight: ThemeHighlight,
    /// Each role's style, then plain text's, made the first time code is drawn.
    styles: Vec<HighlightStyle>,
    /// Texts coloured for drawing once, by language and content, in this theme.
    coloured: HashMap<(SharedString, SharedString), Arc<[LineRuns]>>,
    /// What they hold, their texts and their colours, kept under `COLOURED_MAX_BYTES` by
    /// dropping the oldest.
    coloured_bytes: usize,
    coloured_order: VecDeque<((SharedString, SharedString), usize)>,
    blocks: Blocks,
}

impl PaletteState {
    fn new(tokens: &Tokens, version: u64) -> Self {
        Self {
            version,
            text: tokens.editor.fg.clone(),
            highlight: tokens.highlight.clone(),
            styles: Vec::new(),
            coloured: HashMap::new(),
            coloured_bytes: 0,
            coloured_order: VecDeque::new(),
            blocks: Blocks::default(),
        }
    }

    fn keep(&mut self, key: (SharedString, SharedString), lines: Arc<[LineRuns]>) {
        let run = std::mem::size_of::<(Range<usize>, HighlightStyle)>();
        let bytes = key.1.len()
            + lines
                .iter()
                .map(|line| std::mem::size_of::<LineRuns>() + line.capacity() * run)
                .sum::<usize>();
        self.coloured_bytes += bytes;
        self.coloured_order.push_back((key.clone(), bytes));
        self.coloured.insert(key, lines);
        while self.coloured_bytes > COLOURED_MAX_BYTES {
            let Some((oldest, bytes)) = self.coloured_order.pop_front() else {
                break;
            };
            self.coloured_bytes -= bytes;
            self.coloured.remove(&oldest);
        }
    }
}

impl Global for Palette {}

impl Palette {
    fn styles(&self) -> Ref<'_, [HighlightStyle]> {
        if self.0.borrow().styles.is_empty() {
            let mut state = self.0.borrow_mut();
            let roles = shared().styles.roles();
            state.styles = roles
                .iter()
                .map(|role| colour(&state.highlight, role))
                .chain([Some(theme::color(&state.text))])
                .map(|color| HighlightStyle {
                    color,
                    ..HighlightStyle::default()
                })
                .collect();
        }
        Ref::map(self.0.borrow(), |state| state.styles.as_slice())
    }
}

pub fn install(cx: &mut App) {
    let state = PaletteState::new(Tokens::get(cx), 0);
    cx.set_global(Palette(Rc::new(RefCell::new(state))));
}

/// Takes the code colours of the current theme.
pub fn restyle(cx: &mut App) {
    let palette = cx.global::<Palette>().clone();
    let version = palette.0.borrow().version + 1;
    *palette.0.borrow_mut() = PaletteState::new(Tokens::get(cx), version);
}

/// Changes whenever the theme does, so lines coloured in an older one can be told apart.
pub fn version(cx: &App) -> u64 {
    cx.global::<Palette>().0.borrow().version
}

/// The theme's colour for a role of the scope table, which names the theme's `highlight` keys.
fn colour(highlight: &ThemeHighlight, role: &str) -> Option<gpui_kit::Hsla> {
    let css = match role {
        "keyword" => &highlight.keyword,
        "string" => &highlight.string,
        "comment" => &highlight.comment,
        "number" => &highlight.number,
        "function" => &highlight.function,
        "type" => &highlight.kind,
        "variable" => &highlight.variable,
        "property" => &highlight.property,
        "tag" => &highlight.tag,
        "operator" => &highlight.operator,
        "link" => &highlight.link,
        "invalid" => &highlight.invalid,
        "meta" => &highlight.meta,
        "heading" => &highlight.heading,
        _ => return None,
    };
    Some(theme::color(css))
}

/// A token's style, with `plain` for text no role colours.
fn resolve(style: Style, palette: &[HighlightStyle], plain: HighlightStyle) -> HighlightStyle {
    let mut resolved = style
        .role
        .and_then(|role| palette.get(role as usize).copied())
        .unwrap_or(plain);
    if style.italic {
        resolved.font_style = Some(FontStyle::Italic);
    }
    if style.bold {
        resolved.font_weight = Some(FontWeight::BOLD);
    }
    if style.underline {
        resolved.underline = Some(UnderlineStyle {
            thickness: px(1.),
            color: resolved.color,
            wavy: false,
        });
    }
    resolved
}

/// Whether there is a grammar for a language id, as `file_icons::language` names it.
pub fn knows(language: &str) -> bool {
    shared().library.language(language).is_some()
}

/// A line's styled runs, in bytes from the line's start. Plain text has none.
pub type LineRuns = Vec<(Range<usize>, HighlightStyle)>;

/// Every line of `text` coloured in `language`, for code drawn rather than edited,
/// such as chat code blocks and diffs, worked out off the main thread. `None` for a
/// language with no grammar.
pub fn colour_lines(language: &str, text: SharedString, cx: &App) -> Task<Option<Arc<[LineRuns]>>> {
    if let Some(lines) = coloured_lines(language, &text, cx) {
        return Task::ready(Some(lines));
    }
    let language = SharedString::from(language.to_owned());
    let spans = cx.background_executor().spawn({
        let (language, text) = (language.clone(), text.clone());
        async move {
            let shared = shared();
            textmate_highlight::highlight(&shared.library, &shared.styles, &language, &text)
        }
    });
    cx.spawn(async move |cx| {
        let spans = spans.await?;
        Some(cx.update(|cx| {
            let palette = cx.global::<Palette>().clone();
            let lines: Arc<[LineRuns]> = {
                let styles = palette.styles();
                spans
                    .iter()
                    .map(|line| {
                        line.iter()
                            .map(|span| {
                                let style = resolve(span.style, &styles, HighlightStyle::default());
                                (span.start as usize..span.end as usize, style)
                            })
                            .collect()
                    })
                    .collect()
            };
            palette.0.borrow_mut().keep((language, text), lines.clone());
            lines
        }))
    })
}

/// The lines `colour_lines` worked out for this text in this theme, if it has.
fn coloured_lines(language: &str, text: &SharedString, cx: &App) -> Option<Arc<[LineRuns]>> {
    let state = cx.global::<Palette>().0.borrow();
    state
        .coloured
        .get(&(SharedString::from(language.to_owned()), text.clone()))
        .cloned()
}

/// What a chat does once a code block's colours come: draws it again.
pub type BlockColoured = Rc<dyn Fn(&mut App)>;

/// A chat code block's colours in `language`, worked out off the main thread, then `coloured`
/// is called. A block that grows, as one does while an agent writes it, keeps the colours it
/// had until its new lines are coloured, and only the lines from its last one on are worked
/// out again. `None` for a language with no grammar or a block too long to colour.
pub fn block_runs(
    language: &str,
    code: &SharedString,
    coloured: &BlockColoured,
    cx: &mut App,
) -> Option<CodeRuns> {
    if code.len() > BLOCK_MAX_BYTES || !knows(language) {
        return None;
    }
    let palette = cx.global::<Palette>().clone();
    let plain = palette.styles().last().copied().unwrap_or_default();
    let mut state = palette.0.borrow_mut();
    let version = state.version;
    let blocks = &mut state.blocks;
    blocks.used += 1;
    let used = blocks.used;
    let found = blocks.find(language, code);
    let at = found.unwrap_or_else(|| {
        blocks.next += 1;
        let runs = blocks.shown_shorter(language, code, plain);
        blocks.blocks.push(Block {
            id: blocks.next,
            language: language.to_owned().into(),
            text: code.clone(),
            runs,
            coloured: 0,
            document: None,
            last_line: 0,
            last_line_start: 0,
            working: false,
            document_bytes: 0,
            bytes: 0,
            used,
            coloured_with: None,
        });
        blocks.blocks.len() - 1
    });
    let block = &mut blocks.blocks[at];
    block.used = used;
    block.coloured_with = Some(coloured.clone());
    let grew = block.text != *code;
    if grew {
        block.text = code.clone();
        block.runs = plain_after(&block.runs, block.coloured, code.len(), plain);
    }
    if block.coloured < code.len() {
        #[cfg(feature = "counts")]
        gpui_transcript::counts::add(&gpui_transcript::counts::UNCOLOURED, 1);
        if !block.working {
            start_colouring(block, version, cx);
        }
    }
    let runs = block.runs.clone();
    if grew || found.is_none() {
        blocks.settle(at);
    }
    Some(runs)
}

/// The chat code blocks coloured in this theme, the least recently drawn let go past
/// `BLOCKS_MAX` or `BLOCKS_MAX_BYTES`.
#[derive(Default)]
struct Blocks {
    blocks: Vec<Block>,
    bytes: usize,
    /// Counts draws, so the least recently drawn block is the one with the lowest.
    used: u64,
    next: u64,
}

struct Block {
    id: u64,
    language: SharedString,
    /// The text as last drawn.
    text: SharedString,
    runs: CodeRuns,
    /// How far into `text` the runs are coloured; past it they are plain.
    coloured: usize,
    /// Each coloured line's grammar state, so more lines carry on from them; away while
    /// `working`.
    document: Option<Document>,
    /// The coloured text's last line, and where it starts.
    last_line: usize,
    last_line_start: usize,
    working: bool,
    /// What `document` takes, and what the whole block takes.
    document_bytes: usize,
    bytes: usize,
    used: u64,
    /// Tells the last chat to draw the block that its colours have come.
    coloured_with: Option<BlockColoured>,
}

impl Blocks {
    /// The block `code` is, or the one it grew from.
    fn find(&self, language: &str, code: &str) -> Option<usize> {
        let same = |block: &Block| block.language == language;
        self.blocks
            .iter()
            .position(|block| same(block) && block.text == code)
            .or_else(|| {
                self.blocks
                    .iter()
                    .enumerate()
                    .filter(|(_, block)| same(block) && code.starts_with(block.text.as_ref()))
                    .max_by_key(|(_, block)| block.text.len())
                    .map(|(at, _)| at)
            })
    }

    /// What a new block shows until it is coloured: the colours of a longer one it starts
    /// as, as when the fence closing a block that streamed in had come only in part, or plain.
    fn shown_shorter(&self, language: &str, code: &str, plain: HighlightStyle) -> CodeRuns {
        let longer = self.blocks.iter().find(|block| {
            block.language == language && block.text.starts_with(code) && block.coloured > 0
        });
        let Some(longer) = longer else {
            return plain_after(&CodeRuns::from([]), 0, code.len(), plain);
        };
        let len = code.len().min(longer.coloured);
        let runs: CodeRuns = longer
            .runs
            .iter()
            .filter(|(range, _)| range.start < len)
            .map(|(range, style)| (range.start..range.end.min(len), *style))
            .collect();
        plain_after(&runs, len, code.len(), plain)
    }

    /// Counts the block at `at` afresh, then lets the least recently drawn others go while
    /// there are too many or they take too much.
    fn settle(&mut self, at: usize) {
        let block = &mut self.blocks[at];
        let bytes = block.text.len()
            + block.runs.len() * std::mem::size_of::<(Range<usize>, HighlightStyle)>()
            + block.document_bytes;
        self.bytes = self.bytes + bytes - std::mem::replace(&mut block.bytes, bytes);
        let kept = block.id;
        while self.blocks.len() > BLOCKS_MAX || self.bytes > BLOCKS_MAX_BYTES {
            let Some(oldest) = self
                .blocks
                .iter()
                .enumerate()
                .filter(|(_, block)| block.id != kept)
                .min_by_key(|(_, block)| block.used)
                .map(|(at, _)| at)
            else {
                break;
            };
            self.bytes -= self.blocks.swap_remove(oldest).bytes;
        }
    }
}

/// `runs` coloured as far as `coloured`, and plain from there to `len`.
fn plain_after(runs: &CodeRuns, coloured: usize, len: usize, plain: HighlightStyle) -> CodeRuns {
    let kept = runs.partition_point(|(range, _)| range.start < coloured);
    runs[..kept]
        .iter()
        .cloned()
        .chain((coloured < len).then_some((coloured..len, plain)))
        .collect()
}

/// A block's lines from `from` on, coloured carrying on from `document`, or from its first
/// line without one.
struct Colouring {
    document: Document,
    document_bytes: usize,
    lines: Vec<Vec<Span>>,
    last_line: usize,
    last_line_start: usize,
}

fn colour_block(
    document: Option<Document>,
    language: &str,
    text: &str,
    from: usize,
) -> Option<Colouring> {
    let lines: Vec<&str> = text
        .split('\n')
        .map(|line| line.strip_suffix('\r').unwrap_or(line))
        .collect();
    let last_line = lines.len() - 1;
    let (mut document, from) = match document {
        Some(mut document) => {
            document.edit(from, from, last_line);
            (document, from)
        }
        None => {
            let session = shared().library.session(language)?;
            let mut document = Document::new(session, Some(MAX_LINE_LENGTH));
            document.reset(lines.len());
            (document, 0)
        }
    };
    while document.pending_line().is_some() {
        if document
            .tokenize(&shared().styles, |line| lines[line], lines.len())
            .is_empty()
        {
            break;
        }
    }
    Some(Colouring {
        lines: (from..lines.len())
            .map(|line| document.spans(line).to_vec())
            .collect(),
        document_bytes: document.bytes(),
        document,
        last_line,
        last_line_start: text.rfind('\n').map_or(0, |at| at + 1),
    })
}

fn start_colouring(block: &mut Block, version: u64, cx: &mut App) {
    block.working = true;
    let (id, language, text) = (block.id, block.language.clone(), block.text.clone());
    let (document, from) = (block.document.take(), block.last_line);
    let colouring = cx.background_executor().spawn({
        let text = text.clone();
        async move { colour_block(document, &language, &text, from) }
    });
    cx.spawn(async move |cx| {
        let colouring = colouring.await;
        cx.update(|cx| block_coloured(id, version, text, colouring, cx));
    })
    .detach();
}

/// Takes in a block's new colours, then colours what it has grown by since, if it has.
fn block_coloured(
    id: u64,
    version: u64,
    text: SharedString,
    colouring: Option<Colouring>,
    cx: &mut App,
) {
    let palette = cx.global::<Palette>().clone();
    let styles = palette.styles().to_vec();
    let plain = styles.last().copied().unwrap_or_default();
    let mut state = palette.0.borrow_mut();
    if state.version != version {
        return;
    }
    let blocks = &mut state.blocks;
    let Some(at) = blocks.blocks.iter().position(|block| block.id == id) else {
        return;
    };
    let block = &mut blocks.blocks[at];
    block.working = false;
    let Some(colouring) = colouring else {
        block.coloured = usize::MAX;
        return;
    };
    let kept = block
        .runs
        .partition_point(|(range, _)| range.start < block.last_line_start);
    let mut runs: Vec<_> = block.runs[..kept].to_vec();
    let mut start = block.last_line_start;
    for (line, spans) in text[start..].split('\n').zip(&colouring.lines) {
        let mut cursor = start;
        for span in spans {
            let (from, to) = (start + span.start as usize, start + span.end as usize);
            if cursor < from {
                runs.push((cursor..from, plain));
            }
            let mut style = resolve(span.style, &styles, plain);
            style.color = style.color.or(plain.color);
            runs.push((from..to, style));
            cursor = to;
        }
        if cursor < start + line.len() {
            runs.push((cursor..start + line.len(), plain));
        }
        start += line.len() + 1;
    }
    if text.len() < block.text.len() {
        runs.push((text.len()..block.text.len(), plain));
    }
    block.runs = runs.into();
    block.coloured = text.len();
    block.document = Some(colouring.document);
    block.document_bytes = colouring.document_bytes;
    block.last_line = colouring.last_line;
    block.last_line_start = colouring.last_line_start;
    let coloured = block.coloured_with.clone();
    if block.coloured < block.text.len() {
        start_colouring(block, version, cx);
    }
    blocks.settle(at);
    drop(state);
    #[cfg(feature = "counts")]
    gpui_transcript::counts::add(&gpui_transcript::counts::COLOURED, 1);
    if let Some(coloured) = coloured {
        coloured(cx);
    }
}

/// The editor's highlighters: one per document, for a language id with a grammar.
pub fn highlighters(cx: &App) -> InputHighlighterFactory {
    let palette = cx.global::<Palette>().clone();
    Rc::new(move |language| {
        knows(language).then(|| {
            Box::new(Highlighter::new(language, palette.clone())) as Box<dyn InputHighlighter>
        })
    })
}

/// A line's braces in order, `true` for an opening one, outside strings and comments,
/// and its indent, so folds are worked out without reading the lines again.
#[derive(Clone, Default)]
struct Shape {
    braces: Box<[bool]>,
    indent: Option<u32>,
}

struct Model {
    text: Rope,
    document: Option<Document>,
    /// Whether the grammar is loading, so later updates leave the document to the load.
    loading: bool,
    shapes: Vec<Shape>,
    /// How many lines from the top drawing needs tokenized.
    wanted: usize,
    folding: bool,
    folds: Vec<FoldRange>,
}

impl Model {
    /// Pending lines still to tokenize before the ones drawing needs.
    fn behind(&self) -> usize {
        let Some(document) = &self.document else {
            return 0;
        };
        let until = self.wanted.min(document.line_count());
        document
            .pending_line()
            .map_or(0, |next| until.saturating_sub(next))
    }

    fn tokenize(&mut self, until: usize) {
        let Self {
            text,
            document,
            shapes,
            ..
        } = self;
        let Some(document) = document else {
            return;
        };
        while document.pending_line().is_some_and(|next| next < until) {
            let done = document.tokenize(&shared().styles, |row| line_text(text, row), until);
            if done.is_empty() {
                break;
            }
            for row in done {
                shapes[row] = shape(&line_text(text, row), document.spans(row));
            }
        }
    }

    fn edit(&mut self, edit: InputEdit) {
        let (start, old_end, new_end) = (
            edit.start_position.row,
            edit.old_end_position.row,
            edit.new_end_position.row,
        );
        if let Some(document) = &mut self.document {
            document.edit(start, old_end, new_end);
        }
        let fresh = std::iter::repeat_n(Shape::default(), new_end - start + 1);
        if start >= self.shapes.len() {
            self.shapes.resize(start, Shape::default());
            self.shapes.extend(fresh);
        } else {
            let old_end = old_end.min(self.shapes.len() - 1).max(start);
            self.shapes.splice(start..=old_end, fresh);
        }
    }

    fn reset(&mut self) {
        let lines = self.text.lines_len();
        if let Some(document) = &mut self.document {
            document.reset(lines);
        }
        self.shapes = vec![Shape::default(); lines];
    }

    fn refold(&mut self) {
        self.folds = if self.folding {
            folds(&self.shapes)
        } else {
            Vec::new()
        };
    }
}

fn line_text(text: &Rope, row: usize) -> String {
    let line = text.slice_line(row).to_string();
    match line.strip_suffix('\r') {
        Some(line) => line.to_owned(),
        None => line,
    }
}

fn lock(model: &Mutex<Model>) -> MutexGuard<'_, Model> {
    model
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Loads the grammar on a document's first highlight, then tokenizes as far as
/// drawing needs, a chunk at a time so drawing never waits on it for long. Gives the
/// folds when the document has them.
fn catch_up(model: &Mutex<Model>, language: &str) -> Option<Vec<FoldRange>> {
    if lock(model).loading {
        let session = shared().library.session(language);
        let mut model = lock(model);
        model.loading = false;
        model.document = Some(Document::new(session?, Some(MAX_LINE_LENGTH)));
        model.reset();
    }
    loop {
        let mut model = lock(model);
        let Some(next) = model.document.as_ref()?.pending_line() else {
            break;
        };
        let until = model.wanted.min(model.text.lines_len());
        if next >= until {
            break;
        }
        model.tokenize((next + BACKGROUND_CHUNK).min(until));
    }
    let mut model = lock(model);
    model.refold();
    model.folding.then(|| model.folds.clone())
}

struct Highlighter {
    language: SharedString,
    model: Arc<Mutex<Model>>,
    palette: Palette,
    wake: Arc<Notify>,
    worker: Option<Task<()>>,
}

impl Highlighter {
    fn new(language: &str, palette: Palette) -> Self {
        Self {
            language: language.to_owned().into(),
            model: Arc::new(Mutex::new(Model {
                text: Rope::new(),
                document: None,
                loading: false,
                shapes: Vec::new(),
                wanted: AHEAD,
                folding: false,
                folds: Vec::new(),
            })),
            palette,
            wake: Arc::default(),
            worker: None,
        }
    }

    /// Starts the worker that catches the document up away from the main thread
    /// whenever it is woken, then repaints the editor and gives it the folds.
    fn start_worker(&mut self, window: &mut Window, cx: &mut Context<EditorState>) {
        let model = self.model.clone();
        let language = self.language.clone();
        let wake = self.wake.clone();
        self.worker = Some(cx.spawn_in(window, async move |editor, cx| loop {
            wake.notified().await;
            let model = model.clone();
            let language = language.clone();
            let folds = cx
                .background_executor()
                .spawn(async move { catch_up(&model, &language) })
                .await;
            let updated = editor.update(cx, |editor, cx| match folds {
                Some(folds) => editor.apply_highlighter_fold_candidates(folds, cx),
                None => cx.notify(),
            });
            if updated.is_err() {
                break;
            }
        }));
    }
}

impl InputHighlighter for Highlighter {
    fn language(&self) -> SharedString {
        self.language.clone()
    }

    fn update(
        &mut self,
        edit: Option<InputEdit>,
        text: &Rope,
        folding: bool,
        window: &mut Window,
        cx: &mut Context<EditorState>,
    ) {
        if self.worker.is_none() {
            self.start_worker(window, cx);
        }
        let mut model = lock(&self.model);
        model.text = text.clone();
        model.folding = folding;
        if text.len() <= WHOLE_MAX_BYTES {
            model.wanted = usize::MAX;
        } else if model.wanted == usize::MAX {
            model.wanted = AHEAD;
        }
        match (&model.document, edit) {
            (Some(document), Some(edit)) if document.line_count() > 0 => model.edit(edit),
            (Some(_), _) => model.reset(),
            (None, _) => {
                model.loading = true;
                drop(model);
                self.wake.notify_one();
                return;
            }
        }
        if model.behind() > SYNC_MAX_LINES {
            drop(model);
            self.wake.notify_one();
            return;
        }
        let until = model.wanted;
        model.tokenize(until);
        model.refold();
    }

    fn styles(
        &self,
        range: &Range<usize>,
        _: &dyn HighlightStyleResolver,
    ) -> Vec<(Range<usize>, HighlightStyle)> {
        let mut model = lock(&self.model);
        let palette = self.palette.styles();
        let plain = palette.last().copied().unwrap_or_default();
        let mut runs = Vec::new();
        let mut cursor = range.start;
        let first = model.text.offset_to_point(range.start).row;
        let last = model.text.offset_to_point(range.end).row;
        if model.wanted <= last + AHEAD / 2 {
            model.wanted = last + AHEAD;
        }
        if model.behind() > 0 {
            self.wake.notify_one();
        }
        if let Some(document) = &model.document {
            for row in first..=last.min(document.line_count().saturating_sub(1)) {
                let line_start = model.text.line_start_offset(row);
                for span in document.spans(row) {
                    let start = (line_start + span.start as usize).max(range.start);
                    let end = (line_start + span.end as usize).min(range.end);
                    if start >= end || start < cursor {
                        continue;
                    }
                    if cursor < start {
                        runs.push((cursor..start, plain));
                    }
                    runs.push((start..end, resolve(span.style, &palette, plain)));
                    cursor = end;
                }
            }
        }
        if cursor < range.end {
            runs.push((cursor..range.end, plain));
        }
        runs
    }

    fn fold_ranges(&self, _: &Rope) -> Vec<FoldRange> {
        lock(&self.model).folds.clone()
    }
}

/// A line's shape: its braces outside strings and comments, and its indent.
fn shape(line: &str, spans: &[Span]) -> Shape {
    let quiet = &shared().quiet;
    let mut span = spans.iter().peekable();
    let mut braces = Vec::new();
    for (at, character) in line.char_indices() {
        if character != '{' && character != '}' {
            continue;
        }
        while span
            .peek()
            .is_some_and(|candidate| candidate.end as usize <= at)
        {
            span.next();
        }
        let inside = span.peek().is_some_and(|candidate| {
            candidate.start as usize <= at
                && candidate
                    .style
                    .role
                    .is_some_and(|role| quiet.contains(&role))
        });
        if !inside {
            braces.push(character == '{');
        }
    }
    let trimmed = line.trim_start();
    Shape {
        braces: braces.into(),
        indent: (!trimmed.is_empty()).then(|| (line.len() - trimmed.len()) as u32),
    }
}

/// Folds between matching braces, or, in a document with none, over each block
/// indented deeper than the line that opens it.
fn folds(shapes: &[Shape]) -> Vec<FoldRange> {
    let mut opened = Vec::new();
    let mut ranges = Vec::new();
    let mut braced = false;
    for (row, shape) in shapes.iter().enumerate() {
        for &open in shape.braces.iter() {
            braced = true;
            if open {
                opened.push(row);
            } else if let Some(start) = opened.pop().filter(|start| row - start >= 2) {
                ranges.push(FoldRange::new(start, row));
            }
        }
    }
    if !braced {
        ranges = indent_folds(shapes);
    }
    ranges.sort_by_key(|range| range.start_line);
    ranges.dedup_by_key(|range| range.start_line);
    ranges
}

fn indent_folds(shapes: &[Shape]) -> Vec<FoldRange> {
    let mut ranges = Vec::new();
    let mut open: Vec<(usize, u32)> = Vec::new();
    let mut last = 0usize;
    for (row, shape) in shapes.iter().enumerate() {
        let Some(depth) = shape.indent else { continue };
        while open.last().is_some_and(|(_, opened)| depth <= *opened) {
            let (start, _) = open.pop().unwrap_or_default();
            if last.saturating_sub(start) >= 2 {
                ranges.push(FoldRange::new(start, last));
            }
        }
        open.push((row, depth));
        last = row;
    }
    while let Some((start, _)) = open.pop() {
        if last.saturating_sub(start) >= 2 {
            ranges.push(FoldRange::new(start, last));
        }
    }
    ranges
}
